query RacesWinOdds($date: String, $venueCode: String, $oddsTypes: [OddsType]) {
  raceMeetingProfile(date: $date, venueCode: $venueCode) {
    races {
      no
      status
      runners {
        no
        status
      } 
    }
    pmPools(oddsTypes: $oddsTypes) {
      id
      oddsNodes {
        combString
        hotFavourite
        oddsValue
      }
      lastUpdateTime
    }
  }
}
